package com.flippingfriend.companion;
import com.flippingfriend.model.FillEstimate; import com.flippingfriend.model.FillModel; import java.util.ArrayList; import java.util.List;
/** Pure fail-closed two-leg fill measurement without plausibility filtering or selection. */
final class BuyReplacementQuantityFillEvaluator {
 private final FillModel fillModel; BuyReplacementQuantityFillEvaluator(FillModel f){fillModel=f;}
 BuyReplacementQuantityFillEvaluationSet evaluate(BuyReplacementQuantityFillInputContext s,long at){if(s==null||fillModel==null||at<s.getComposedAt()||s.getComposedAt()+CompanionBuyReplacementReadinessPolicy.MAX_INPUT_AGE_SECONDS<at||s.getFillCurve()==null||s.getFillCurve().isEmpty()||!Double.isFinite(s.getEffectiveHorizonHours())||s.getEffectiveHorizonHours()<=0||!Double.isFinite(s.getSeasonalMultiplier())||s.getSeasonalMultiplier()<=0||s.getInputs()==null||s.getInputs().isEmpty())return null;List<BuyReplacementQuantityFillEvaluation> out=new ArrayList<>(s.getInputs().size());for(BuyReplacementQuantityFillInput x:s.getInputs()){if(!valid(x,s))return null;FillEstimate b=fillModel.estimateBuy(s.getFillCurve(),x.getBuyPrice(),x.getQuantity(),s.getEffectiveHorizonHours(),s.getSeasonalMultiplier());FillEstimate e=fillModel.estimateSell(s.getFillCurve(),x.getSellPrice(),x.getQuantity(),s.getEffectiveHorizonHours(),s.getSeasonalMultiplier());if(!valid(b)||!valid(e))return null;out.add(new BuyReplacementQuantityFillEvaluation(x,b.getProbability(),b.getExpectedHours(),b.getUnitsPerHour(),b.getWaitHours(),e.getProbability(),e.getExpectedHours(),e.getUnitsPerHour(),e.getWaitHours()));}return new BuyReplacementQuantityFillEvaluationSet(s,out,at);}
 private static boolean valid(BuyReplacementQuantityFillInput x,BuyReplacementQuantityFillInputContext s){return x!=null&&x.getBuyPrice()>0&&x.getSellPrice()>x.getBuyPrice()&&x.getFillableQuantity()==s.getExactRemainderQuantity()&&x.getQuantity()>0&&x.getQuantity()<=x.getFillableQuantity()&&x.getSizeGridIndex()>=0&&Double.isFinite(x.getSizeShare())&&x.getSizeShare()>0;} private static boolean valid(FillEstimate e){return e!=null&&Double.isFinite(e.getProbability())&&e.getProbability()>=0&&e.getProbability()<=1&&!Double.isNaN(e.getExpectedHours())&&e.getExpectedHours()>=0&&Double.isFinite(e.getUnitsPerHour())&&e.getUnitsPerHour()>=0&&!Double.isNaN(e.getWaitHours())&&e.getWaitHours()>=0;}
}
